 if(!error&&age<std::chrono::hours(24)){auto bytes=read(path);if(!bytes.empty()&&bytes.size()<8*1024*1024){IStream* stream{};if(SUCCEEDED(CreateStreamOnHGlobal(nullptr,TRUE,&stream))){ULONG written{};stream->Write(bytes.data(),ULONG(bytes.size()),&written);LARGE_INTEGER zero{};stream->Seek(zero,STREAM_SEEK_SET,nullptr);ICoreWebView2WebResourceResponse* response{};if(SUCCEEDED(env->CreateWebResourceResponse(stream,200,L"OK",L"Content-Type: text/html; charset=utf-8\r\nCache-Control: no-cache\r\nX-Bili-Space-Cache: hit\r\n",&response))){args->put_Response(response);response->Release();if(testing)log("official HTML cache hit");}stream->Release();}}}
